"use client";

import { Easing, interpolate, useCurrentFrame } from "remotion";

export interface VolumetricRaysProps {
  text?: string;
  fontSize?: number;
  fontWeight?: number;
  /** Base ray color. Hex values get `rayOpacity` baked in. */
  rayColor?: string;
  /** Alpha applied to a hex `rayColor` (ignored for non-hex colors). */
  rayOpacity?: number;
  background?: string;
  textColor?: string;
  intensity?: number;
  speed?: number;
  className?: string;
}

const FONT_FAMILY =
  'Inter, var(--font-geist-sans), -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif';

/**
 * Apply an alpha channel to a hex color (#rgb or #rrggbb), returning an
 * rgba() string. Non-hex inputs are returned unchanged so callers can pass
 * a pre-mixed rgba()/color value directly.
 */
export function withAlpha(color: string, alpha: number): string {
  const hex = color.trim();
  const short = /^#([0-9a-f]{3})$/i.exec(hex);
  const long = /^#([0-9a-f]{6})$/i.exec(hex);
  let r: number;
  let g: number;
  let b: number;
  if (short) {
    const [rc, gc, bc] = short[1];
    r = Number.parseInt(rc + rc, 16);
    g = Number.parseInt(gc + gc, 16);
    b = Number.parseInt(bc + bc, 16);
  } else if (long) {
    r = Number.parseInt(long[1].slice(0, 2), 16);
    g = Number.parseInt(long[1].slice(2, 4), 16);
    b = Number.parseInt(long[1].slice(4, 6), 16);
  } else {
    return color;
  }
  const clamped = Math.min(1, Math.max(0, alpha));
  return `rgba(${r},${g},${b},${clamped})`;
}

/**
 * Layered "god rays" hero background built entirely from CSS masks — the one
 * cinematic beat of a keynote-style trailer. The trick:
 *
 * 1. Render the same title twice. The back layer is scaled wider than tall
 *    and heavily blurred — that's the halo the rays bloom out of.
 * 2. Sweep a conic-gradient clipped to the text shape so slow light shafts
 *    drift through the lettering.
 * 3. The front layer is the solid title, so the eye reads "letters lit from
 *    behind" rather than a flat glow.
 *
 * Use it once per video: it is the dramatic moment, not a repeating texture.
 */
export function VolumetricRays({
  text = "Acme 2.0",
  fontSize = 200,
  fontWeight = 700,
  rayColor = "#266DF0",
  rayOpacity = 0.22,
  background = "#0A0A0B",
  textColor = "#FAFAFA",
  intensity = 0.6,
  speed = 0.5,
  className,
}: VolumetricRaysProps) {
  const frame = useCurrentFrame() * speed;

  // Soft accent tint used by every light layer — low alpha keeps the rays
  // atmospheric instead of neon.
  const rayTint = withAlpha(rayColor, rayOpacity);

  // Slow source rotation: the rays drift around their origin so the scene
  // never looks frozen even though the motion is sub-conscious.
  const rotation = interpolate(frame, [0, 240], [-4, 8]);
  // Bloom ramps in over the first second — the "lights up" moment.
  const bloomOpacity = interpolate(frame, [0, 30], [0, 0.95 * intensity], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  // The halo slowly breathes with a frame-driven sine wave.
  const haloPulse = 0.6 + Math.sin(frame / 14) * 0.15;

  const sharedTextStyle: React.CSSProperties = {
    position: "absolute",
    inset: 0,
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    fontFamily: FONT_FAMILY,
    fontSize,
    fontWeight,
    letterSpacing: "-0.02em",
    textAlign: "center",
    whiteSpace: "nowrap",
  };

  return (
    <div
      className={className}
      style={{
        position: "absolute",
        inset: 0,
        background,
        overflow: "hidden",
      }}
    >
      {/* 1. The bloom: same title, scaled and blurred, anchored to the
            bottom so the light rises from below the baseline. */}
      <div
        style={{
          ...sharedTextStyle,
          color: rayTint,
          filter: `blur(${60 * intensity}px)`,
          transform: "scale(1.2, 1.6)",
          transformOrigin: "center bottom",
          opacity: bloomOpacity * haloPulse,
        }}
      >
        {text}
      </div>

      {/* 2. Conic-gradient ray mask clipped to the text shape so the light
            shafts only show up where the letters are. */}
      <div
        style={{
          ...sharedTextStyle,
          backgroundImage: `conic-gradient(from ${rotation}deg at 50% 100%,
            transparent 0deg,
            ${rayTint} 20deg,
            transparent 40deg,
            ${rayTint} 80deg,
            transparent 100deg,
            ${rayTint} 140deg,
            transparent 160deg,
            ${rayTint} 200deg,
            transparent 220deg,
            ${rayTint} 260deg,
            transparent 280deg,
            ${rayTint} 320deg,
            transparent 360deg)`,
          color: "transparent",
          WebkitBackgroundClip: "text",
          backgroundClip: "text",
          opacity: 0.5 * intensity,
          filter: "blur(2px)",
        }}
      >
        {text}
      </div>

      {/* 3. Front title: the solid launch line rises in on a fast,
            high-damping ease-out — no bounce. */}
      <div
        style={{
          ...sharedTextStyle,
          color: textColor,
          textShadow: `0 0 ${30 * intensity}px ${rayTint}`,
          opacity: interpolate(frame, [0, 24], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
            easing: Easing.out(Easing.cubic),
          }),
          translate: interpolate(frame, [0, 30], ["0px 14px", "0px 0px"], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
            easing: Easing.out(Easing.cubic),
          }),
        }}
      >
        {text}
      </div>

      {/* 4. Floor light bleed — a wide radial gradient at the baseline so
            the rays feel grounded. */}
      <div
        style={{
          position: "absolute",
          left: 0,
          right: 0,
          bottom: 0,
          height: 200,
          pointerEvents: "none",
          background: `radial-gradient(ellipse at 50% 100%, ${rayTint} 0%, transparent 60%)`,
          opacity: bloomOpacity,
        }}
      />
    </div>
  );
}
